export function evaluate({ inputs, time }) {
  const u = Number(inputs.launchSpeed ?? 4.0);
  const g = Number(inputs.gravity ?? 9.8);
  const m = Number(inputs.mass ?? 1.0);

  const apexTime = u / g;
  const apexHeight = (u * u) / (2 * g);
  const flightDuration = (2 * u) / g;

  const t = Math.max(0, Math.min(time, flightDuration));
  const height = u * t - 0.5 * g * t * t;
  const velocity = u - g * t;
  const acceleration = -g;
  const force = m * g;

  let motionState = 'Rising';
  if (t === 0) {
    motionState = 'Ready to toss';
  } else if (Math.abs(t - apexTime) < 0.015) {
    motionState = 'At the top';
  } else if (t >= flightDuration - 0.005) {
    motionState = 'Back at launch height';
  } else if (t > apexTime) {
    motionState = 'Falling';
  }

  const leftLane = sdk.panel({ x: 20, y: 30, w: 270, h: 370, title: 'Motion', state: motionState, id: 'lane.toss' });
  const rightLane = sdk.panel({ x: 310, y: 30, w: 310, h: 370, title: 'Velocity vs Time', state: 'a = -' + g.toFixed(1) + ' m/s²', id: 'lane.plot' });

  const heightAxis = sdk.axis('axis.height', {
    x: 75,
    y: 360,
    length: 290,
    orientation: 'y',
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: 'Height',
    unit: 'm'
  });

  const ballY = 360 - (Math.max(0, height) / 2.2) * 290;
  const ballX = 135;
  const ballObj = sdk.circle('ball.toss', ballX, ballY, 26, { role: 'learner' });

  const vVec = sdk.vector('vec.v', { x: ballX, y: ballY }, { value: velocity, direction: 'up', scale: 12, label: 'v' });
  const aVec = sdk.vector('vec.a', { x: ballX + 28, y: ballY }, { value: acceleration, direction: 'up', scale: 8, label: 'a' });

  const calloutObj = sdk.callout(ballX + 55, ballY - 20, [
    'v = ' + velocity.toFixed(2) + ' m/s',
    'a = ' + acceleration.toFixed(2) + ' m/s²',
    'Fg = ' + force.toFixed(1) + ' N'
  ], { id: 'callout.toss' });

  const pts = [];
  const stepCount = 20;
  for (let i = 0; i <= stepCount; i++) {
    const st = (flightDuration * i) / stepCount;
    const sv = u - g * st;
    pts.push({ x: Number(st.toFixed(3)), y: Number(sv.toFixed(3)) });
  }

  const plotObj = sdk.plot('plot.vt', {
    x: 330,
    y: 55,
    w: 270,
    h: 325,
    axes: {
      x: { label: 'Time', min: 0, max: 1.8, unit: 's' },
      y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' }
    },
    series: [
      { label: 'v(t)', kind: 'line', points: pts }
    ],
    marker: { x: Number(t.toFixed(3)), y: Number(velocity.toFixed(3)), label: 't' }
  });

  const objects = [
    ...leftLane,
    ...rightLane,
    heightAxis,
    ballObj,
    ...vVec,
    ...aVec,
    ...calloutObj,
    plotObj
  ];

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: 'velocity', value: Number(velocity.toFixed(2)) },
        { id: 'acceleration', value: Number(acceleration.toFixed(2)) },
        { id: 'force', value: Number(force.toFixed(2)) },
        { id: 'motionState', value: motionState }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime,
      apexHeight,
      height,
      velocity,
      acceleration,
      force
    }
  };
}
